create table if not exists public.ils_professional_assignment_gate_stress_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_gate_stress_tests enable row level security; revoke all on public.ils_professional_assignment_gate_stress_tests from anon,authenticated; insert into public.ils_professional_assignment_gate_stress_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('AUTH_USER_MISMATCH','BLOCK','BLOCK',true,'Gate requires auth.uid() to equal target professional user.'),('MISSING_WORK_CODE','BLOCK','BLOCK',true,'Null work code is rejected.'),('NO_ALLOW_DECISION','BLOCK','BLOCK',true,'Assignment requires matching ALLOW decision.'),('INACTIVE_TRUST_PROFILE','BLOCK','BLOCK',true,'Professional trust profile must be ACTIVE.'),('IDENTITY_UNVERIFIED','BLOCK','BLOCK',true,'Identity verification is mandatory.'),('QUALIFICATION_UNVERIFIED','BLOCK','BLOCK',true,'Qualification verification is mandatory.'),('REGISTRATION_UNVERIFIED','BLOCK','BLOCK',true,'Professional registration verification is mandatory.'),('CAPABILITY_UNVERIFIED','BLOCK','BLOCK',true,'Capability verification is mandatory.'),('REQUIRED_CAPABILITY_MISSING','BLOCK','BLOCK',true,'At least one required capability must be verified.'),('SUPERVISION_REQUIRED','BLOCK','BLOCK',true,'Supervision-required assignments are not auto-created by this gate.'),('PRO_REVIEW_REQUIRED','BLOCK','BLOCK',true,'Professional-review-required assignments are not auto-created by this gate.'),('VALID_CHAIN','ALLOW','ALLOW',true,'Requires authenticated self, active verified trust, verified required capability, matching ALLOW decision, and owned work item.');